import sys,json,encodings.idna as idna,unicodedata
assert sys.version_info[:3]==(3,14,7) and unicodedata.unidata_version=='16.0.0'
def fault(e):
 d=dict(name=type(e).__name__,message=str(e),suppressContext=e.__suppress_context__)
 if isinstance(e,(UnicodeEncodeError,UnicodeDecodeError)):
  d.update(encoding=e.encoding,object=list(e.object) if isinstance(e.object,bytes) else list(map(ord,e.object)),start=str(e.start),end=str(e.end),reason=e.reason)
 if e.__context__ is not None:d['context']=fault(e.__context__)
 return d
mode,rows=json.load(sys.stdin)
for row in rows:
 row.pop('result',None);row.pop('consumed',None);row.pop('error',None)
 value=bytes(row['input']) if row.get('binary') or row.get('operation')=='decode' else ''.join(map(chr,row['input']))
 try:
  if mode=='domain': result,consumed=getattr(idna.Codec(),row['operation'])(value,row['errors'])
  elif mode=='encode':result,consumed=idna.IncrementalEncoder()._buffer_encode(value,row['errors'],row['final'])
  else:result,consumed=idna.IncrementalDecoder()._buffer_decode(value,row['errors'],row['final'])
  row.update(result=list(map(ord,result)) if isinstance(result,str) else list(result),consumed=consumed)
 except Exception as e:row['error']=fault(e)
print(json.dumps(rows))
